    "\tFOREIGN KEY(tenant_id, category_id, product_id, project_id, publication_id, "
    "publication_revision, process_id, process_revision) REFERENCES "
    "manufacturing_baseline_publications (tenant_id, category_id, product_id, project_id, id, "
    "revision, process_id, process_revision), \n"
    "\tCHECK (revision=1 AND build_revision>0), \n"
    "\tCHECK (lot_revision=1 AND actual_configuration_revision=1), \n"
    "\tCHECK (engineering_revision>0 AND process_revision>0), \n"
    "\tCHECK ((publication_id IS NULL AND publication_revision IS NULL) OR (publication_id IS NOT "
    "NULL AND publication_revision>0))\n"
    ")\n"
    "\n",
    "CREATE INDEX ix_native_pilot_runs_category_id ON native_pilot_runs (category_id)",
    "CREATE INDEX ix_native_pilot_runs_tenant_id ON native_pilot_runs (tenant_id)",
    "\n"
    "CREATE TABLE native_pilot_currents (\n"
    "\tproduct_id UUID NOT NULL, \n"
    "\tproject_id UUID NOT NULL, \n"
    "\tpilot_id UUID NOT NULL, \n"
    "\towner_id UUID NOT NULL, \n"
    "\tvisibility VARCHAR(16) NOT NULL, \n"
    "\trevision INTEGER NOT NULL, \n"
    "\tlatest_observation_id UUID, \n"
    "\tepoch INTEGER NOT NULL, \n"
    "\tid UUID NOT NULL, \n"
    "\ttenant_id UUID NOT NULL, \n"
    "\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tcategory_id UUID NOT NULL, \n"
    "\tPRIMARY KEY (id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id) REFERENCES products (tenant_id, category_id, "
    "id), \n"
    "\tFOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, "
    "id), \n"
    "\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n"
    "\tCHECK (visibility IN ('private','category','audience')), \n"
    "\tUNIQUE (tenant_id, category_id, product_id, project_id, pilot_id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id, project_id, owner_id, visibility, pilot_id) "
    "REFERENCES native_pilot_runs (tenant_id, category_id, product_id, project_id, owner_id, "
    "visibility, id), \n"
    "\tCHECK ((revision=1 AND epoch=1 AND latest_observation_id IS NULL) OR (revision>1 AND "
    "epoch=revision AND latest_observation_id IS NOT NULL))\n"
    ")\n"
    "\n",
    "CREATE INDEX ix_native_pilot_currents_category_id ON native_pilot_currents (category_id)",
    "CREATE INDEX ix_native_pilot_currents_tenant_id ON native_pilot_currents (tenant_id)",
    "\n"
    "CREATE TABLE native_pilot_observations (\n"
    "\tpilot_id UUID NOT NULL, \n"
    "\tpilot_revision_before INTEGER NOT NULL, \n"
    "\trevision INTEGER NOT NULL, \n"
    "\tprevious_observation_id UUID, \n"
    "\toperation VARCHAR(80) NOT NULL, \n"
    "\trecord JSONB NOT NULL, \n"
    "\tfixed_scope JSONB, \n"
    "\tprojection JSONB, \n"
    "\tproduct_id UUID NOT NULL, \n"
    "\tproject_id UUID NOT NULL, \n"
    "\towner_id UUID NOT NULL, \n"
    "\twriter_id UUID NOT NULL, \n"
    "\tactor_id UUID NOT NULL, \n"
    "\trequester_id UUID NOT NULL, \n"
    "\tvisibility VARCHAR(16) NOT NULL, \n"
    "\tstatus VARCHAR(16) NOT NULL, \n"
    "\twrite_tier VARCHAR(4) NOT NULL, \n"
    "\tinput_snapshot JSONB NOT NULL, \n"
    "\tpayload_sha256 VARCHAR(64) NOT NULL, \n"
    "\tmaterial_snapshot JSONB NOT NULL, \n"
    "\trequired_source_read_set JSONB NOT NULL, \n"
    "\tsources JSONB NOT NULL, \n"
    "\tsource_basis JSONB NOT NULL, \n"
    "\tauthority_snapshot JSONB NOT NULL, \n"
    "\tgaps JSONB NOT NULL, \n"
    "\tcommand_id UUID NOT NULL, \n"
    "\treceipt_id UUID NOT NULL, \n"
    "\tshared_proof_id UUID NOT NULL, \n"
    "\tshared_proof_revision INTEGER NOT NULL, \n"
    "\tproof_consumed_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tproof_expires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\ttoken_sha256 VARCHAR(64) NOT NULL, \n"
    "\tmaterial_sha256 VARCHAR(64) NOT NULL, \n"
    "\tread_set_sha256 VARCHAR(64) NOT NULL, \n"
    "\tintent_digest VARCHAR(64) NOT NULL, \n"
    "\trequest_digest VARCHAR(64) NOT NULL, \n"
    "\tid UUID NOT NULL, \n"
    "\ttenant_id UUID NOT NULL, \n"
    "\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tcategory_id UUID NOT NULL, \n"
    "\tPRIMARY KEY (id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id) REFERENCES products (tenant_id, category_id, "
    "id), \n"
    "\tFOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, "
    "id), \n"
    "\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n"
    "\tCHECK (visibility IN ('private','category','audience')), \n"
    "\tUNIQUE (tenant_id, shared_proof_id), \n"
    "\tUNIQUE (tenant_id, receipt_id), \n"
    "\tUNIQUE (tenant_id, command_id), \n"
    "\tUNIQUE (tenant_id, product_id, actor_id, operation, intent_digest), \n"
    "\tFOREIGN KEY(tenant_id, writer_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, requester_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, shared_proof_id) REFERENCES confirmations (tenant_id, id) DEFERRABLE "
    "INITIALLY DEFERRED, \n"
    "\tFOREIGN KEY(tenant_id, receipt_id) REFERENCES action_receipts (tenant_id, id) DEFERRABLE "
    "INITIALLY DEFERRED, \n"
    "\tCHECK (operation='npi.pilot.result.record' AND write_tier='T1' AND status='recorded'), \n"
    "\tCHECK (actor_id=requester_id AND writer_id=actor_id), \n"
    "\tCHECK (shared_proof_revision>0), \n"
    "\tCHECK (proof_consumed_at<=created_at AND created_at<proof_expires_at), \n"
    "\tCHECK (jsonb_typeof(required_source_read_set)='array' AND "
    "jsonb_array_length(required_source_read_set)>0 AND jsonb_typeof(sources)='array' AND "
    "jsonb_array_length(sources)>0), \n"
    "\tCHECK (payload_sha256 ~ '^[a-f0-9]{64}$' AND token_sha256 ~ '^[a-f0-9]{64}$' AND "
    "material_sha256 ~ '^[a-f0-9]{64}$' AND read_set_sha256 ~ '^[a-f0-9]{64}$' AND intent_digest ~ "
    "'^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$'), \n"
    "\tUNIQUE (tenant_id, product_id, id, revision), \n"
    "\tUNIQUE (tenant_id, category_id, product_id, project_id, pilot_id, revision), \n"
    "\tUNIQUE (tenant_id, category_id, product_id, project_id, owner_id, visibility, pilot_id, id, "
    "revision), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id, project_id, owner_id, visibility, pilot_id) "
    "REFERENCES native_pilot_runs (tenant_id, category_id, product_id, project_id, owner_id, "
    "visibility, id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id, project_id, owner_id, visibility, pilot_id, "
    "previous_observation_id, pilot_revision_before) REFERENCES native_pilot_observations (tenant_id, "
    "category_id, product_id, project_id, owner_id, visibility, pilot_id, id, revision) DEFERRABLE "
    "INITIALLY DEFERRED, \n"
    "\tCHECK (pilot_revision_before>0 AND revision=pilot_revision_before+1), \n"
    "\tCHECK ((pilot_revision_before=1 AND previous_observation_id IS NULL) OR "
    "(pilot_revision_before>1 AND previous_observation_id IS NOT NULL AND "
    "previous_observation_id<>id))\n"
    ")\n"
    "\n",
    "CREATE INDEX ix_native_pilot_observations_category_id ON native_pilot_observations (category_id)",
    "CREATE INDEX ix_native_pilot_observations_tenant_id ON native_pilot_observations (tenant_id)",
    "ALTER TABLE native_pilot_currents ADD CONSTRAINT fk_native_pilot_current_observation FOREIGN "
    "KEY(tenant_id, category_id, product_id, project_id, owner_id, visibility, pilot_id, "
    "latest_observation_id, revision) REFERENCES native_pilot_observations (tenant_id, category_id, "
    "product_id, project_id, owner_id, visibility, pilot_id, id, revision) DEFERRABLE INITIALLY "
    "DEFERRED",
    "CREATE FUNCTION public.assert_native_pilot_members(t uuid,target uuid,kind text) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE v record; c public.confirmations; r public.action_receipts; command jsonb; event_name "
    "text;\n"
    "BEGIN\n"
    " IF kind='pilot_run' THEN\n"
    "  SELECT * INTO STRICT v FROM public.native_pilot_runs WHERE tenant_id=t AND id=target;\n"
    "  event_name='pilot.created';\n"
    " ELSIF kind='pilot_observation' THEN\n"
    "  SELECT * INTO STRICT v FROM public.native_pilot_observations WHERE tenant_id=t AND id=target;\n"
    "  event_name='pilot.results_recorded';\n"
    " ELSE RAISE EXCEPTION 'Unknown native Pilot subject' USING ERRCODE='23514'; END IF;\n"
    " SELECT * INTO STRICT c FROM public.confirmations WHERE tenant_id=t AND id=v.shared_proof_id;\n"
    " SELECT * INTO STRICT r FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n"
    " command=v.input_snapshot->'command';\n"
    " IF "
    "ROW(c.category_id,c.product_id,c.actor_id,c.subject_type,c.subject_id,c.operation,c.revision)\n"
    "  IS DISTINCT FROM ROW(v.category_id,v.product_id,v.actor_id,'product'::varchar,\n"
    "    v.product_id,v.operation,v.shared_proof_revision)\n"
    "  OR c.consumed IS DISTINCT FROM true OR c.token_hash IS DISTINCT FROM v.token_sha256\n"
    "  OR c.payload_digest IS DISTINCT FROM v.material_sha256\n"
    "  OR c.snapshot IS DISTINCT FROM v.input_snapshot->'review'\n"
    "  OR c.expires_at IS NULL OR c.expires_at IS DISTINCT FROM v.proof_expires_at\n"
    "  OR NOT(c.created_at<=v.proof_consumed_at AND v.proof_consumed_at<=v.created_at\n"
    "    AND v.created_at<=r.created_at AND r.created_at<c.expires_at)\n"
    "  OR ROW(r.category_id,r.product_id,r.command_id,r.confirmation_id,r.actor_id,r.requester_id,\n"
    "    "
    "r.operation,r.subject_type,r.subject_id,r.subject_revision,r.visibility,r.request_digest,r.intent_digest)\n"
    "   IS DISTINCT FROM ROW(v.category_id,v.product_id,v.command_id,v.shared_proof_id,\n"
    "    "
    "v.actor_id,v.requester_id,v.operation,kind::varchar,v.id,v.revision,v.visibility,v.request_digest,v.intent_digest)\n"
    "  OR r.run_id IS NOT NULL OR r.agent_run_id IS NOT NULL\n"
    "  OR r.result IS DISTINCT FROM "
    "jsonb_build_object('id',v.id,'revision',v.revision,'status','recorded')\n"
    "  OR (SELECT count(*) FROM public.action_receipts x WHERE x.tenant_id=t\n"
    "    AND x.operation=v.operation AND x.subject_type=kind AND x.subject_id=v.id AND "
    "x.subject_revision=v.revision)<>1\n"
    "  OR (SELECT count(*) FROM public.audit_entries a WHERE a.tenant_id=t AND a.receipt_id=r.id)<>1\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.audit_entries a WHERE a.tenant_id=t AND "
    "a.category_id=v.category_id\n"
    "    AND a.receipt_id=r.id AND a.actor_id=v.actor_id AND a.operation=v.operation AND "
    "a.created_at>=v.created_at)\n"
    "  OR (SELECT count(*) FROM public.outbox_events e WHERE e.tenant_id=t AND e.receipt_id=r.id)<>1\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.tenant_id=t AND "
    "e.category_id=v.category_id\n"
    "    AND e.receipt_id=r.id AND e.actor_id=v.actor_id AND e.type=event_name AND e.subject_id=v.id\n"
    "    AND e.subject_revision=v.revision AND e.schema_version=1 AND e.correlation_id=v.command_id\n"
    "    AND e.created_at>=v.created_at)\n"
    "  OR v.input_snapshot->>'original_key_sha256' IS NULL\n"
    "  OR v.input_snapshot->>'original_key_sha256' !~ '^[a-f0-9]{64}$'\n"
    "  OR command ? 'idempotency_key' OR (command->'payload') ? 'confirmation_token'\n"
    "  OR (v.input_snapshot->'semantic') ? 'confirmation_token'\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.request_keys k WHERE k.tenant_id=t AND "
    "k.category_id=v.category_id\n"
    "    AND k.receipt_id=r.id AND k.actor_id=v.actor_id AND k.digest=v.request_digest\n"
    "    AND "
    "encode(sha256(convert_to(k.key,'UTF8')),'hex')=v.input_snapshot->>'original_key_sha256')\n"
    " THEN RAISE EXCEPTION 'Native Pilot original T1 proof receipt audit event or request mismatch'\n"
    "  USING ERRCODE='23514'; END IF;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.native_pilot_source_line(t uuid,category uuid,product uuid,src jsonb) "
    "RETURNS text\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE a public.artifact_versions; position text[]; line text;\n"
    "BEGIN\n"
    " position=regexp_match(src->>'position','^line:([1-9][0-9]*);quote_sha256:([a-f0-9]{64})$');\n"
    " IF src->>'kind' IS DISTINCT FROM 'artifact' OR position IS NULL\n"
    "  OR jsonb_typeof(src->'revision') IS DISTINCT FROM 'number' THEN\n"
    "  RAISE EXCEPTION 'Native Pilot original requires its exact artifact line' USING "
    "ERRCODE='23514'; END IF;\n"
    " SELECT * INTO STRICT a FROM public.artifact_versions WHERE tenant_id=t AND "
    "category_id=category\n"
    "  AND (product_id IS NULL OR product_id=product) AND id::text=src->>'id'\n"
    "  AND revision::text=src->>'revision' AND status='active';\n"
    " "
    "line=(regexp_split_to_array(a.content,E'\\r\\n|[\\n\\r\\013\\014\\034-\\036\\u0085\\u2028\\u2029]'))[position[1]::integer];\n"
    " IF line IS NULL OR encode(sha256(convert_to(line,'UTF8')),'hex')<>position[2] THEN\n"
    "  RAISE EXCEPTION 'Native Pilot original line hash changed' USING ERRCODE='23514'; END IF;\n"
    " RETURN line;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.native_pilot_original_values(t uuid,category uuid,product uuid,src jsonb) "
    "RETURNS jsonb\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "BEGIN\n"
    " RETURN public.native_pilot_source_line(t,category,product,src)::jsonb;\n"
    "EXCEPTION WHEN invalid_text_representation THEN\n"
    " RAISE EXCEPTION 'Native Pilot original values must be a supported JSON line' USING "
    "ERRCODE='23514';\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.assert_native_pilot_physical(t uuid,pilot uuid,snapshot jsonb,at "
    "timestamptz) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE r public.native_pilot_runs; b public.builds; l public.build_lots;\n"
    " a public.actual_configurations; e public.engineering_configurations; p "
    "public.process_revisions;\n"
    " pub public.manufacturing_baseline_publications; ref jsonb; applicability jsonb;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT r FROM public.native_pilot_runs WHERE tenant_id=t AND id=pilot;\n"
    " SELECT * INTO STRICT b FROM public.builds WHERE tenant_id=t AND id=r.build_id;\n"
    " SELECT * INTO STRICT l FROM public.build_lots WHERE tenant_id=t AND id=r.lot_id;\n"
    " SELECT * INTO STRICT a FROM public.actual_configurations WHERE tenant_id=t AND "
    "id=r.actual_configuration_id;\n"
    " SELECT * INTO STRICT e FROM public.engineering_configurations WHERE tenant_id=t AND "
    "id=r.engineering_configuration_id;\n"
    " SELECT * INTO STRICT p FROM public.process_revisions WHERE tenant_id=t AND id=r.process_id;\n"
    " IF ROW(b.category_id,b.product_id,b.project_id,b.revision)\n"
    "   IS DISTINCT FROM ROW(r.category_id,r.product_id,r.project_id,r.build_revision)\n"
    "  OR ROW(l.category_id,l.product_id,l.project_id,l.build_id,l.build_revision,l.revision,\n"
    "    l.actual_configuration_id,l.actual_configuration_revision,l.unit)\n"
    "   IS DISTINCT FROM "
    "ROW(r.category_id,r.product_id,r.project_id,r.build_id,r.build_revision,r.lot_revision,\n"
    "    "
    "r.actual_configuration_id,r.actual_configuration_revision,(r.details->'basis'->>'unit')::varchar)\n"
    "  OR ROW(a.category_id,a.product_id,a.project_id,a.build_id,a.build_revision,a.revision,\n"
    "    a.actual_engineering_configuration_id,a.actual_engineering_revision,\n"
    "    a.actual_manufacturing_configuration_id,a.actual_manufacturing_revision)\n"
    "   IS DISTINCT FROM ROW(r.category_id,r.product_id,r.project_id,r.build_id,r.build_revision,\n"
    "    "
    "r.actual_configuration_revision,r.engineering_configuration_id,r.engineering_revision,r.process_id,r.process_revision)\n"
    "  OR ROW(e.category_id,e.product_id,e.revision,p.category_id,p.product_id,p.revision,\n"
    "    p.engineering_configuration_id,p.engineering_revision)\n"
    "   IS DISTINCT FROM "
    "ROW(r.category_id,r.product_id,r.engineering_revision,r.category_id,r.product_id,\n"
    "    r.process_revision,r.engineering_configuration_id,r.engineering_revision)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.project_product_links link WHERE link.tenant_id=t\n"
    "    AND link.product_id=r.product_id AND link.project_id=r.project_id\n"
    "    AND link.definition_id=e.definition_id AND link.definition_revision=e.definition_revision)\n"
    "  OR snapshot->'scope' IS DISTINCT FROM "
    "jsonb_build_object('tenant_id',t,'product_id',r.product_id,'project_id',r.project_id)\n"
    "  OR snapshot->>'category_id' IS DISTINCT FROM r.category_id::text\n"
    "  OR snapshot->>'purpose' IS DISTINCT FROM r.purpose OR snapshot->'basis' IS DISTINCT FROM "
    "r.details->'basis'\n"
    "  OR snapshot->>'qualification' IS DISTINCT FROM 'unknown'\n"
    "  OR snapshot->'start_authorized' IS DISTINCT FROM 'false'::jsonb\n"
    "  OR snapshot->'manufacturing_release' IS DISTINCT FROM 'null'::jsonb\n"
    "  OR snapshot->'build'->>'id' IS DISTINCT FROM b.id::text\n"
    "  OR snapshot->'build'->>'revision' IS DISTINCT FROM b.revision::text\n"
    "  OR snapshot->'lot'->>'id' IS DISTINCT FROM l.id::text\n"
    "  OR snapshot->'lot'->>'revision' IS DISTINCT FROM l.revision::text\n"
    "  OR snapshot->'lot'->>'observed_unit_count' IS DISTINCT FROM l.observed_unit_count::text\n"
    "  OR snapshot->'lot'->'observation'->>'nature' IS DISTINCT FROM l.observation_nature\n"
    "  OR snapshot->'actual_configuration'->>'id' IS DISTINCT FROM a.id::text\n"
    "  OR snapshot->'actual_configuration'->>'revision' IS DISTINCT FROM a.revision::text\n"
    "  OR snapshot->'engineering_configuration'->>'id' IS DISTINCT FROM e.id::text\n"
    "  OR snapshot->'engineering_configuration'->>'revision' IS DISTINCT FROM e.revision::text\n"
    "  OR snapshot->'process'->>'id' IS DISTINCT FROM p.id::text\n"
    "  OR snapshot->'process'->>'revision' IS DISTINCT FROM p.revision::text\n"
    "  OR snapshot->'process'->'operations' IS DISTINCT FROM p.operations\n"
    "  OR snapshot->'process'->>'site' IS DISTINCT FROM p.site OR snapshot->'process'->>'line' IS "
    "DISTINCT FROM p.line\n"
    " THEN RAISE EXCEPTION 'Native Pilot actual lot build configurations or project changed' USING "
    "ERRCODE='23514'; END IF;\n"
    " IF r.publication_id IS NULL THEN\n"
    "  IF snapshot->'publication' IS DISTINCT FROM 'null'::jsonb THEN\n"
    "   RAISE EXCEPTION 'Native Pilot cannot invent a publication' USING ERRCODE='23514'; END IF;\n"
    " ELSE\n"
    "  SELECT * INTO STRICT pub FROM public.manufacturing_baseline_publications WHERE tenant_id=t AND "
    "id=r.publication_id;\n"
    "  PERFORM public.assert_manufacturing_publication_members(t,pub.id);\n"
    "  applicability=pub.body->'declaration'->'applicability';\n"
    "  IF "
    "ROW(pub.category_id,pub.product_id,pub.project_id,pub.revision,pub.process_id,pub.process_revision,pub.purpose)\n"
    "    IS DISTINCT FROM "
    "ROW(r.category_id,r.product_id,r.project_id,r.publication_revision,r.process_id,r.process_revision,r.purpose)\n"
    "   OR snapshot->'publication'->>'id' IS DISTINCT FROM pub.id::text\n"
    "   OR snapshot->'publication'->>'revision' IS DISTINCT FROM pub.revision::text\n"
    "   OR snapshot->'publication'->'body' IS DISTINCT FROM pub.body\n"
    "   OR (applicability->>'site' IS NOT NULL AND applicability->>'site' IS DISTINCT FROM p.site)\n"
    "   OR (applicability->>'valid_from' IS NOT NULL AND "
    "at<(applicability->>'valid_from')::timestamptz)\n"
    "   OR (applicability->>'valid_until' IS NOT NULL AND "
    "at>=(applicability->>'valid_until')::timestamptz)\n"
    "   OR (r.details->'line'<>'null'::jsonb AND applicability->'lines'<>'null'::jsonb\n"
    "    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(applicability->'lines') x WHERE "
    "x=r.details->'line'))\n"
    "  THEN RAISE EXCEPTION 'Native Pilot fixed publication or applicability mismatch' USING "
    "ERRCODE='23514'; END IF;\n"
    "  FOR ref IN SELECT value FROM jsonb_array_elements(r.details->'instructions')\n"
    "   UNION ALL SELECT r.details->'control_plan' WHERE r.details->'control_plan'<>'null'::jsonb "
    "LOOP\n"
    "   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pub.body->'documents') x\n"
    "    WHERE x->>'kind'=ref->>'kind' AND x->>'id'=ref->>'id' AND x->'revision'=ref->'revision') "
    "THEN\n"
    "    RAISE EXCEPTION 'Native Pilot instruction is outside its fixed publication' USING "
    "ERRCODE='23514'; END IF;\n"
    "  END LOOP;\n"
    " END IF;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.assert_native_pilot_common(t uuid,target uuid,kind text) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE v record; root public.native_pilot_runs; c public.confirmations; command jsonb; review "
    "jsonb;\n"
    " semantic jsonb; body jsonb; basis jsonb; dep jsonb; ref jsonb; vx xid; cx xid; rx xid;\n"
    "BEGIN\n"
    " IF kind='pilot_run' THEN\n"
    "  SELECT x.*,x.xmin AS tx INTO STRICT v FROM public.native_pilot_runs x WHERE x.tenant_id=t AND "
    "x.id=target;\n"
    "  SELECT * INTO STRICT root FROM public.native_pilot_runs WHERE tenant_id=t AND id=target;\n"
    "  body=jsonb_build_object('details',v.details,'statistics_basis',v.statistics_basis);\n"
    " ELSIF kind='pilot_observation' THEN\n"
    "  SELECT x.*,x.xmin AS tx INTO STRICT v FROM public.native_pilot_observations x WHERE "
    "x.tenant_id=t AND x.id=target;\n"
    "  SELECT * INTO STRICT root FROM public.native_pilot_runs WHERE tenant_id=t AND id=v.pilot_id;\n"
    "  "
    "body=jsonb_build_object('record',v.record,'fixed_scope',v.fixed_scope,'projection',v.projection,\n"
    "    "
    "'pilot_id',v.pilot_id,'pilot_revision_before',v.pilot_revision_before,'previous_observation_id',v.previous_observation_id);\n"
    " ELSE RAISE EXCEPTION 'Unknown native Pilot subject' USING ERRCODE='23514'; END IF;\n"
    " vx=v.tx;\n"
    " SELECT * INTO STRICT c FROM public.confirmations WHERE tenant_id=t AND id=v.shared_proof_id;\n"
    " SELECT xmin INTO cx FROM public.confirmations WHERE tenant_id=t AND id=c.id;\n"
    " SELECT xmin INTO rx FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n"
    " PERFORM public.assert_native_pilot_members(t,target,kind);\n"
    " command=v.input_snapshot->'command'; semantic=v.input_snapshot->'semantic'; "
    "review=v.input_snapshot->'review';\n"
    " "
    "body=body||jsonb_build_object('material',v.material_snapshot,'gaps',v.gaps,'qualification','unknown',\n"
    "   'start_authorized',false,'manufacturing_release',null,'external_delivery',false);\n"
    " IF v.actor_id IS DISTINCT FROM public.scope_actor() OR v.requester_id IS DISTINCT FROM "
    "public.scope_requester()\n"
    "  OR v.actor_id<>v.requester_id OR v.writer_id<>v.actor_id OR NOT "
    "public.category_access(t,v.category_id,true)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.principals x WHERE x.tenant_id=t AND x.id=v.actor_id AND "
    "x.kind='human' AND x.active)\n"
    "  OR (v.visibility='private' AND v.owner_id<>v.actor_id)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.products p WHERE p.tenant_id=t AND "
    "p.category_id=v.category_id\n"
    "    AND p.id=v.product_id AND p.revision=v.shared_proof_revision)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.tenant_id=t AND "
    "p.category_id=v.category_id\n"
    "    AND p.product_id=v.product_id AND p.id=v.project_id AND p.purpose=root.purpose)\n"
    "  OR vx IS DISTINCT FROM cx OR vx IS DISTINCT FROM rx\n"
    "  OR ROW(v.category_id,v.product_id,v.project_id,v.owner_id,v.visibility)\n"
    "   IS DISTINCT FROM "
    "ROW(root.category_id,root.product_id,root.project_id,root.owner_id,root.visibility)\n"
    "  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v.input_snapshot) key)\n"
    "   IS DISTINCT FROM "
    "ARRAY['command','original_key_sha256','previous_current','review','semantic']\n"
    "  OR command->>'operation' IS DISTINCT FROM v.operation\n"
    "  OR command->>'command_id' IS DISTINCT FROM v.command_id::text\n"
    "  OR command->>'category_id' IS DISTINCT FROM v.category_id::text\n"
    "  OR command->>'product_id' IS DISTINCT FROM v.product_id::text\n"
    "  OR command->>'expected_revision' IS DISTINCT FROM v.shared_proof_revision::text\n"
    "  OR command->'payload' IS DISTINCT FROM semantic\n"
    "  OR command->'source_read_set' IS DISTINCT FROM v.required_source_read_set\n"
    "  OR review->>'operation' IS DISTINCT FROM v.operation OR review->'after' IS DISTINCT FROM body\n"
    "  OR review->'authority' IS DISTINCT FROM v.authority_snapshot\n"
    "  OR review->'read_basis' IS DISTINCT FROM v.source_basis\n"
    "  OR review->'required_source_read_set' IS DISTINCT FROM v.required_source_read_set\n"
    "  OR v.material_snapshot->'pilot'->>'product_revision' IS DISTINCT FROM "
    "v.shared_proof_revision::text\n"
    " THEN RAISE EXCEPTION 'Native Pilot requires its actual human T1 scope material and common "
    "transaction' USING ERRCODE='23514'; END IF;\n"
    " PERFORM "
    "public.assert_native_pilot_physical(t,root.id,v.material_snapshot->'pilot',v.created_at);\n"
    " IF EXISTS(SELECT 1 FROM (\n"
    "   SELECT value AS dependency FROM "
    "jsonb_array_elements(v.authority_snapshot->'required_source_read_set')\n"
    "   UNION ALL SELECT jsonb_build_object('artifact_id',x->>'id','expected_revision',x->'revision') "
    "FROM jsonb_array_elements(v.sources) x\n"
    "   UNION ALL SELECT "
    "jsonb_build_object('artifact_id',x->>'id','expected_revision',x->'revision')\n"
    '    FROM jsonb_path_query(semantic,\'$.** ? (@.kind == "artifact" && exists(@.id) && '
    "exists(@.revision))') x\n"
    "   UNION ALL SELECT reads.value FROM jsonb_each(v.material_snapshot->'pilot') child\n"
    "    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN "
    "jsonb_typeof(child.value->'required_source_read_set')='array'\n"
    "     THEN child.value->'required_source_read_set' ELSE '[]'::jsonb END) reads\n"
    "  ) required WHERE NOT v.required_source_read_set @> jsonb_build_array(required.dependency))\n"
    "  OR (SELECT count(DISTINCT x->>'artifact_id') FROM "
    "jsonb_array_elements(v.required_source_read_set) x)\n"
    "    <>jsonb_array_length(v.required_source_read_set)\n"
    " THEN RAISE EXCEPTION 'Native Pilot source closure omits actual material' USING ERRCODE='23514'; "
    "END IF;\n"
    " basis=v.source_basis->'artifact_sources';\n"
    " IF jsonb_typeof(basis) IS DISTINCT FROM 'array' OR "
    "jsonb_array_length(basis)<>jsonb_array_length(v.required_source_read_set)\n"
    "  OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(basis) "
    "x)<>jsonb_array_length(basis) THEN\n"
    "  RAISE EXCEPTION 'Native Pilot complete source basis missing' USING ERRCODE='23514'; END IF;\n"
    " FOR ref IN SELECT value FROM jsonb_array_elements(v.required_source_read_set) LOOP\n"
    "  IF jsonb_typeof(ref->'expected_revision') IS DISTINCT FROM 'number'\n"
    "   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(basis) x JOIN public.artifact_versions a\n"
    "    ON a.tenant_id=t AND a.category_id=v.category_id AND a.id::text=x->>'id'\n"
    "     AND (a.product_id IS NULL OR a.product_id=v.product_id)\n"
    "    WHERE x->>'id'=ref->>'artifact_id' AND x->>'revision'=ref->>'expected_revision'\n"
    "     AND jsonb_typeof(x->'revision')='number' AND a.revision::text=x->>'revision'\n"
    "     AND a.status='active' AND x->>'status'='active' AND a.content_hash=x->>'sha256'\n"
    "     AND a.owner_id::text=x->>'owner_id' AND a.visibility=x->>'visibility'\n"
    "     AND (v.visibility='private' OR a.visibility<>'private')\n"
    "     AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM public.uploaded_originals o\n"
    "      JOIN public.original_security sec ON sec.tenant_id=o.tenant_id AND sec.original_id=o.id\n"
    "      WHERE o.tenant_id=t AND o.category_id=v.category_id AND o.id=a.original_id AND "
    "o.status='parsed'\n"
    "       AND o.revision::text=x->>'original_revision' AND o.content_hash=x->>'original_sha256'\n"
    "       AND o.owner_id::text=x->>'original_owner_id' AND o.visibility=x->>'original_visibility'\n"
    "       AND sec.epoch::text=x->>'security_epoch' AND sec.source_state='active' AND "
    "sec.disposition='active'\n"
    "       AND (v.visibility='private' OR o.visibility<>'private'))))\n"
    "  THEN RAISE EXCEPTION 'Native Pilot actual source version security or audience changed' USING "
    "ERRCODE='23514'; END IF;\n"
    " END LOOP;\n"
    " FOR dep IN SELECT value FROM jsonb_array_elements(v.sources) LOOP\n"
    "  PERFORM public.native_pilot_source_line(t,v.category_id,v.product_id,dep);\n"
    " END LOOP;\n"
    " IF v.authority_snapshot->'scope' IS DISTINCT FROM "
    "jsonb_build_object('tenant_id',t,'product_id',v.product_id,'project_id',v.project_id)\n"
    "  OR v.authority_snapshot->>'subject_id' IS DISTINCT FROM v.actor_id::text\n"
    "  OR v.authority_snapshot->>'operation' IS DISTINCT FROM v.operation\n"
    "  OR v.authority_snapshot->>'purpose' IS DISTINCT FROM root.purpose\n"
    "  OR v.authority_snapshot->'authorized' IS DISTINCT FROM 'true'::jsonb\n"
    "  OR v.authority_snapshot->'qualified' IS DISTINCT FROM 'true'::jsonb\n"
    "  OR NOT(v.authority_snapshot->'roles' @> '[\"manufacturing\"]'::jsonb)\n"
    "  OR NOT public.capture_authority_time_current(v.authority_snapshot,v.created_at)\n"
    "  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.authority_snapshot->'fact_refs')) THEN\n"
    "  RAISE EXCEPTION 'Native Pilot actual professional authority missing' USING ERRCODE='23514'; "
    "END IF;\n"
    " FOR ref IN SELECT value FROM jsonb_array_elements(v.authority_snapshot->'fact_refs') LOOP\n"
    "  IF NOT EXISTS(SELECT 1 FROM public.professional_authority_facts f JOIN "
    "public.professional_authority_current cur\n"
    "   ON cur.tenant_id=f.tenant_id AND cur.category_id=f.category_id AND "
    "cur.product_id=f.product_id\n"
    "    AND cur.project_id=f.project_id AND cur.subject_id=f.subject_id AND cur.kind=f.kind AND "
    "cur.series_id=f.series_id\n"
    "    AND cur.fact_id=f.id AND cur.fact_revision=f.revision\n"
    "   WHERE f.tenant_id=t AND f.category_id=v.category_id AND f.product_id=v.product_id AND "
    "f.project_id=v.project_id\n"
    "    AND f.subject_id=v.actor_id AND f.id::text=ref->>'id' AND f.revision::text=ref->>'revision'\n"
    "    AND cur.epoch::text=ref->>'epoch' AND f.fact_sha256=ref->>'fact_sha256' AND "
    "f.state=ref->>'state'\n"
    "    AND f.role=ref->>'role' AND f.kind=ref->>'kind' AND f.series_id::text=ref->>'series_id'\n"
    "    AND f.issuer_key=ref->>'issuer_key' AND f.issuer_version=ref->>'issuer_version' AND "
    "f.nature=ref->>'nature'\n"
    "    AND f.operations=ref->'operations' AND f.purposes=ref->'purposes'\n"
    "    AND f.valid_from IS NOT DISTINCT FROM (ref->>'valid_from')::timestamptz\n"
    "    AND f.valid_until IS NOT DISTINCT FROM (ref->>'valid_until')::timestamptz) THEN\n"
    "   RAISE EXCEPTION 'Native Pilot professional Current or fact changed' USING ERRCODE='23514'; "
    "END IF;\n"
    " END LOOP;\n"
    " IF EXISTS(SELECT 1 FROM public.audit_entries x WHERE x.tenant_id=t AND "
    "x.receipt_id=v.receipt_id AND x.xmin IS DISTINCT FROM vx)\n"
    "  OR EXISTS(SELECT 1 FROM public.outbox_events x WHERE x.tenant_id=t AND "
    "x.receipt_id=v.receipt_id AND x.xmin IS DISTINCT FROM vx)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.request_keys k WHERE k.tenant_id=t AND "
    "k.receipt_id=v.receipt_id\n"
    "   AND k.actor_id=v.actor_id AND k.digest=v.request_digest AND k.xmin=vx\n"
    "   AND encode(sha256(convert_to(k.key,'UTF8')),'hex')=v.input_snapshot->>'original_key_sha256') "
    "THEN\n"
    "  RAISE EXCEPTION 'Native Pilot common members must commit together' USING ERRCODE='23514'; END "
    "IF;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.assert_native_pilot_root(t uuid,target uuid) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE v public.native_pilot_runs; expected jsonb; raw jsonb; vx xid;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT v FROM public.native_pilot_runs WHERE tenant_id=t AND id=target;\n"
    " SELECT xmin INTO vx FROM public.native_pilot_runs WHERE tenant_id=t AND id=target;\n"
    " PERFORM public.assert_native_pilot_common(t,target,'pilot_run');\n"
    " IF v.input_snapshot->'semantic' IS DISTINCT FROM jsonb_build_object('project_id',v.project_id,\n"
    "    'details',v.details,'statistics',v.statistics_basis,'visibility',v.visibility)\n"
    "  OR v.details->>'pilot_id' IS DISTINCT FROM v.id::text\n"
    "  OR v.details->>'purpose' IS DISTINCT FROM v.purpose\n"
    "  OR v.details->'basis' IS DISTINCT FROM jsonb_build_object(\n"
    "   'build',jsonb_build_object('kind','build','id',v.build_id,'revision',v.build_revision),\n"
    "   'lot',jsonb_build_object('kind','build_lot','id',v.lot_id,'revision',v.lot_revision),\n"
    "   "
    "'actual_configuration',jsonb_build_object('kind','actual_configuration','id',v.actual_configuration_id,'revision',v.actual_configuration_revision),\n"
    "   "
    "'engineering_configuration',jsonb_build_object('kind','engineering_configuration','id',v.engineering_configuration_id,'revision',v.engineering_revision),\n"
    "   "
    "'process_revision',jsonb_build_object('kind','process_revision','id',v.process_id,'revision',v.process_revision),\n"
    "   'unit',v.details->'basis'->'unit')\n"
    "  OR v.details->'manufacturing_baseline' IS DISTINCT FROM (CASE WHEN v.publication_id IS NULL "
    "THEN 'null'::jsonb\n"
    "   ELSE "
    "jsonb_build_object('kind','manufacturing_baseline','id',v.publication_id,'revision',v.publication_revision) "
    "END)\n"
    "  OR v.input_snapshot->'previous_current' IS DISTINCT FROM 'null'::jsonb\n"
    "  OR v.input_snapshot->'review'->'before' IS DISTINCT FROM 'null'::jsonb\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.native_pilot_currents cur WHERE cur.tenant_id=t\n"
    "   AND cur.category_id=v.category_id AND cur.product_id=v.product_id AND "
    "cur.project_id=v.project_id\n"
    "   AND cur.pilot_id=v.id AND cur.owner_id=v.owner_id AND cur.visibility=v.visibility\n"
    "   AND cur.revision=1 AND cur.epoch=1 AND cur.latest_observation_id IS NULL\n"
    "   AND cur.xmin=vx)\n"
    " THEN RAISE EXCEPTION 'Native Pilot immutable root or initial Current mismatch' USING "
    "ERRCODE='23514'; END IF;\n"
    " IF v.statistics_basis IS NULL THEN\n"
    "  IF coalesce(v.material_snapshot#>'{statistics,statistics}','null'::jsonb) IS DISTINCT FROM "
    "'null'::jsonb\n"
    "   OR v.material_snapshot->'fixed_scope' IS DISTINCT FROM 'null'::jsonb THEN\n"
    "   RAISE EXCEPTION 'Missing native Pilot declaration remains unknown' USING ERRCODE='23514'; END "
    "IF;\n"
    " ELSE\n"
    "  "
    "expected=jsonb_build_object('schema_version','pdos-pilot-statistics-declaration-v1','pilot_id',v.id,\n"
    "    'statistics',v.statistics_basis-'source');\n"
    "  "
    "raw=public.native_pilot_original_values(t,v.category_id,v.product_id,v.statistics_basis->'source');\n"
    "  IF raw IS DISTINCT FROM expected\n"
    "   OR v.material_snapshot->'statistics'->'originals'->'statistics' IS DISTINCT FROM raw\n"
    "   OR v.material_snapshot->'statistics'->'statistics' IS DISTINCT FROM v.statistics_basis THEN\n"
    "   RAISE EXCEPTION 'Native Pilot declaration differs from its actual original values' USING "
    "ERRCODE='23514'; END IF;\n"
    " END IF;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.assert_native_pilot_observation(t uuid,target uuid) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE v public.native_pilot_observations; root public.native_pilot_runs;\n"
    " previous public.native_pilot_observations; expected jsonb; original_record jsonb; raw jsonb; "
    "old_input jsonb; new_input jsonb; vx xid;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT v FROM public.native_pilot_observations WHERE tenant_id=t AND id=target;\n"
    " SELECT xmin INTO vx FROM public.native_pilot_observations WHERE tenant_id=t AND id=target;\n"
    " SELECT * INTO STRICT root FROM public.native_pilot_runs WHERE tenant_id=t AND id=v.pilot_id;\n"
    " PERFORM public.assert_native_pilot_common(t,target,'pilot_observation');\n"
    " PERFORM public.assert_native_pilot_members(t,root.id,'pilot_run');\n"
    " "
    "expected=jsonb_build_object('revision',v.pilot_revision_before,'epoch',v.pilot_revision_before,\n"
    "   'latest_observation_id',v.previous_observation_id);\n"
    " IF v.input_snapshot->'semantic' IS DISTINCT FROM jsonb_build_object('pilot_id',v.pilot_id,\n"
    "    'expected_pilot_revision',v.pilot_revision_before,'record',v.record)\n"
    "  OR v.record->>'observation_id' IS DISTINCT FROM v.id::text\n"
    "  OR v.record->>'expected_pilot_revision' IS DISTINCT FROM v.pilot_revision_before::text\n"
    "  OR v.record->>'previous_observation_id' IS DISTINCT FROM v.previous_observation_id::text\n"
    "  OR v.record->'scope'->'basis' IS DISTINCT FROM root.details->'basis'\n"
    "  OR v.record->'scope'->'manufacturing_baseline' IS DISTINCT FROM "
    "root.details->'manufacturing_baseline'\n"
    "  OR v.record->'scope'->'line' IS DISTINCT FROM root.details->'line'\n"
    "  OR v.record->'scope'->>'nature' IS DISTINCT FROM "
    "v.material_snapshot->'pilot'->'lot'->'observation'->>'nature'\n"
    "  OR (v.record->'observed'->>'occurred_at')::timestamptz>v.created_at\n"
    "  OR v.input_snapshot->'previous_current' IS DISTINCT FROM expected\n"
    "  OR v.input_snapshot->'review'->'before' IS DISTINCT FROM expected\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.native_pilot_currents cur WHERE cur.tenant_id=t\n"
    "   AND cur.category_id=v.category_id AND cur.product_id=v.product_id AND "
    "cur.project_id=v.project_id\n"
    "   AND cur.pilot_id=v.pilot_id AND cur.owner_id=v.owner_id AND cur.visibility=v.visibility\n"
    "   AND cur.revision=v.revision AND cur.epoch=v.revision AND cur.latest_observation_id=v.id AND "
    "cur.xmin=vx)\n"
    "  OR v.fixed_scope IS DISTINCT FROM nullif(v.material_snapshot->'fixed_scope','null'::jsonb)\n"
    "  OR v.material_snapshot->'statistics'->'statistics' IS DISTINCT FROM "
    "coalesce(root.statistics_basis,'null'::jsonb)\n"
    " THEN RAISE EXCEPTION 'Native Pilot observation original CAS or fixed root mismatch' USING "
    "ERRCODE='23514'; END IF;\n"
    " IF v.pilot_revision_before=1 THEN\n"
    "  IF v.previous_observation_id IS NOT NULL OR v.revision<>2 THEN\n"
    "   RAISE EXCEPTION 'First native Pilot observation starts at revision two' USING "
    "ERRCODE='23514'; END IF;\n"
    " ELSE\n"
    "  SELECT * INTO STRICT previous FROM public.native_pilot_observations WHERE tenant_id=t AND "
    "id=v.previous_observation_id;\n"
    "  PERFORM public.assert_native_pilot_members(t,previous.id,'pilot_observation');\n"
    "  IF ROW(previous.category_id,previous.product_id,previous.project_id,previous.pilot_id,\n"
    "    previous.owner_id,previous.visibility,previous.revision)\n"
    "   IS DISTINCT FROM "
    "ROW(v.category_id,v.product_id,v.project_id,v.pilot_id,v.owner_id,v.visibility,v.pilot_revision_before)\n"
    "   OR nullif(v.record->>'correction_reason','') IS NULL THEN\n"
    "   RAISE EXCEPTION 'Native Pilot correction requires its exact predecessor and reason' USING "
    "ERRCODE='23514'; END IF;\n"
    "  IF previous.fixed_scope IS NOT NULL THEN\n"
    "   old_input=CASE WHEN previous.record->'counts'='null'::jsonb THEN "
    "to_jsonb(jsonb_array_length(previous.record->'units'))\n"
    "     ELSE previous.record->'counts'->'input_count' END;\n"
    "   new_input=CASE WHEN v.record->'counts'='null'::jsonb THEN "
    "to_jsonb(jsonb_array_length(v.record->'units'))\n"
    "     ELSE v.record->'counts'->'input_count' END;\n"
    "   IF v.fixed_scope IS NULL OR (v.fixed_scope-'pilot_revision') IS DISTINCT FROM "
    "(previous.fixed_scope-'pilot_revision')\n"
    "    OR old_input IS DISTINCT FROM new_input\n"
    "    OR "
    "(v.record->'observed'->>'occurred_at')::timestamptz<(previous.record->'observed'->>'occurred_at')::timestamptz "
    "THEN\n"
    "    RAISE EXCEPTION 'Native Pilot correction cannot change its fixed scope denominator or "
    "reverse time' USING ERRCODE='23514'; END IF;\n"
    "  END IF;\n"
    " END IF;\n"
    " IF v.fixed_scope IS NULL THEN\n"
    "  IF v.projection IS NOT NULL THEN\n"
    "   RAISE EXCEPTION 'Unknown native Pilot scope cannot assert statistics' USING ERRCODE='23514'; "
    "END IF;\n"
    " ELSE\n"
    "  IF v.fixed_scope->>'pilot_id' IS DISTINCT FROM v.pilot_id::text\n"
    "   OR v.fixed_scope->>'pilot_revision' IS DISTINCT FROM v.pilot_revision_before::text\n"
    "   OR v.fixed_scope->'scope' IS DISTINCT FROM v.material_snapshot->'pilot'->'scope'\n"
    "   OR v.fixed_scope->'yield_scope' IS DISTINCT FROM v.record->'scope'\n"
    "   OR (v.projection IS NOT NULL AND (v.projection->'fixed' IS DISTINCT FROM v.fixed_scope\n"
    "    OR v.projection->>'observation_id' IS DISTINCT FROM v.id::text\n"
    "    OR v.projection->'metrics'->>'process_capability' IS DISTINCT FROM 'NOT_ASSESSED'\n"
    "    OR v.projection->'metrics'->>'factory_qualification' IS DISTINCT FROM 'NOT_ASSESSED'\n"
    "    OR v.projection->'metrics'->'start_authorized' IS DISTINCT FROM 'false'::jsonb\n"
    "    OR v.projection->'metrics'->'manufacturing_release' IS DISTINCT FROM 'null'::jsonb\n"
    "    OR v.projection->'metrics'->'external_delivery_authorized' IS DISTINCT FROM 'false'::jsonb)) "
    "THEN\n"
    "   RAISE EXCEPTION 'Native Pilot fixed statistics cannot grant capability start or release' "
    "USING ERRCODE='23514'; END IF;\n"
    " END IF;\n"
    " "
    "original_record=(v.record-'source')||jsonb_build_object('observed',(v.record->'observed')-'source',\n"
    "  'units',(SELECT coalesce(jsonb_agg(x.value-'source' ORDER BY x.ordinality),'[]'::jsonb)\n"
    "    FROM jsonb_array_elements(v.record->'units') WITH ORDINALITY x),\n"
    "  'exceptions',(SELECT coalesce(jsonb_agg(x.value-'source'-'disposition' ORDER BY "
    "x.ordinality),'[]'::jsonb)\n"
    "    FROM jsonb_array_elements(v.record->'exceptions') WITH ORDINALITY x));\n"
    " "
    "expected=jsonb_build_object('schema_version','pdos-pilot-result-values-v1','pilot_id',v.pilot_id,'record',original_record);\n"
    " raw=public.native_pilot_original_values(t,v.category_id,v.product_id,v.record->'source');\n"
    " IF raw IS DISTINCT FROM expected OR v.material_snapshot->'statistics'->'originals'->'record' IS "
    "DISTINCT FROM raw\n"
    "  OR v.material_snapshot->'statistics'->'record' IS DISTINCT FROM v.record THEN\n"
    "  RAISE EXCEPTION 'Native Pilot observation values differ from the actual original' USING "
    "ERRCODE='23514'; END IF;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.protect_native_pilot_current() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "BEGIN\n"
    " IF TG_OP='INSERT' THEN\n"
    "  IF NEW.revision=1 AND NEW.epoch=1 AND NEW.latest_observation_id IS NULL THEN RETURN NEW; END "
    "IF;\n"
    " ELSIF TG_OP='UPDATE' THEN\n"
    "  IF (to_jsonb(NEW)-ARRAY['revision','epoch','latest_observation_id'])\n"
    "    IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['revision','epoch','latest_observation_id'])\n"
    "   AND NEW.revision=OLD.revision+1 AND NEW.epoch=OLD.epoch+1\n"
    "   AND EXISTS(SELECT 1 FROM public.native_pilot_observations v WHERE v.tenant_id=NEW.tenant_id\n"
    "    AND v.category_id=NEW.category_id AND v.product_id=NEW.product_id AND "
    "v.project_id=NEW.project_id\n"
    "    AND v.pilot_id=NEW.pilot_id AND v.owner_id=NEW.owner_id AND v.visibility=NEW.visibility\n"
    "    AND v.id=NEW.latest_observation_id AND v.revision=NEW.revision\n"
    "    AND v.pilot_revision_before=OLD.revision AND v.previous_observation_id IS NOT DISTINCT FROM "
    "OLD.latest_observation_id)\n"
    "   THEN RETURN NEW; END IF;\n"
    " END IF;\n"
    " RAISE EXCEPTION 'Native Pilot Current only advances one exact observation and epoch' USING "
    "ERRCODE='23514';\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.require_native_pilot_current() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE current_row public.native_pilot_currents; root public.native_pilot_runs; cx xid; rx "
    "xid;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT current_row FROM public.native_pilot_currents WHERE "
    "tenant_id=NEW.tenant_id AND id=NEW.id;\n"
    " SELECT * INTO STRICT root FROM public.native_pilot_runs WHERE tenant_id=NEW.tenant_id AND "
    "id=current_row.pilot_id;\n"
    " SELECT xmin INTO cx FROM public.native_pilot_currents WHERE tenant_id=NEW.tenant_id AND "
    "id=NEW.id;\n"
    " SELECT xmin INTO rx FROM public.native_pilot_runs WHERE tenant_id=NEW.tenant_id AND "
    "id=current_row.pilot_id;\n"
    " IF "
    "ROW(current_row.category_id,current_row.product_id,current_row.project_id,current_row.owner_id,current_row.visibility)\n"
    "   IS DISTINCT FROM "
    "ROW(root.category_id,root.product_id,root.project_id,root.owner_id,root.visibility)\n"
    "  OR current_row.revision<>current_row.epoch\n"
    "  OR (SELECT count(*) FROM public.native_pilot_observations v WHERE v.tenant_id=root.tenant_id\n"
    "    AND v.pilot_id=root.id)<>current_row.revision-1 THEN\n"
    "  RAISE EXCEPTION 'Native Pilot Current requires the complete contiguous observation chain' "
    "USING ERRCODE='23514'; END IF;\n"
    " IF current_row.revision=1 THEN\n"
    "  IF current_row.latest_observation_id IS NOT NULL OR cx IS DISTINCT FROM rx THEN\n"
    "   RAISE EXCEPTION 'Initial native Pilot Current is part of root creation' USING "
    "ERRCODE='23514'; END IF;\n"
    " ELSE\n"
    "  IF NOT EXISTS(SELECT 1 FROM public.native_pilot_observations v WHERE "
    "v.tenant_id=root.tenant_id\n"
    "    AND v.id=current_row.latest_observation_id AND v.pilot_id=root.id\n"
    "    AND v.revision=current_row.revision AND v.xmin=cx) THEN\n"
    "   RAISE EXCEPTION 'Native Pilot Current requires its actual latest observation transaction' "
    "USING ERRCODE='23514'; END IF;\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.protect_native_pilot_proof() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE old_scoped boolean=false; new_scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'INSERT' THEN old_scoped=OLD.operation IN "
    "('npi.pilot.create','npi.pilot.result.record'); END IF;\n"
    " IF TG_OP<>'DELETE' THEN new_scoped=NEW.operation IN "
    "('npi.pilot.create','npi.pilot.result.record'); END IF;\n"
    " IF old_scoped OR new_scoped THEN\n"
    "  IF TG_OP='DELETE' THEN\n"
    "   RAISE EXCEPTION 'Native Pilot confirmation history is retained' USING ERRCODE='23514';\n"
    "  ELSIF TG_OP='INSERT' THEN\n"
    "   IF NEW.consumed IS DISTINCT FROM false OR NEW.expires_at IS NULL THEN\n"
    "    RAISE EXCEPTION 'Native Pilot T1 proof starts unconsumed with its actual deadline' USING "
    "ERRCODE='23514'; END IF;\n"
    "  ELSIF NOT(old_scoped AND new_scoped) OR OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS "
    "DISTINCT FROM true\n"
    "   OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN\n"
    "   RAISE EXCEPTION 'Native Pilot confirmation permits only original false to true' USING "
    "ERRCODE='23514';\n"
    "  END IF;\n"
    " END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n"
    " RETURN NEW;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.require_native_pilot_transition() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "BEGIN\n"
    " IF NEW.operation IN ('npi.pilot.create','npi.pilot.result.record') THEN\n"
    "  IF OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS DISTINCT FROM true\n"
    "   OR (SELECT count(*) FROM (\n"
    "    SELECT id FROM public.native_pilot_runs WHERE tenant_id=NEW.tenant_id AND "
    "shared_proof_id=NEW.id AND operation=NEW.operation\n"
    "    UNION ALL SELECT id FROM public.native_pilot_observations WHERE tenant_id=NEW.tenant_id AND "
    "shared_proof_id=NEW.id AND operation=NEW.operation\n"
    "   ) actual)<>1 THEN\n"
    "   RAISE EXCEPTION 'Consumed native Pilot T1 proof requires exactly one actual subject' USING "
    "ERRCODE='23514'; END IF;\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.protect_native_pilot_receipt() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'INSERT' THEN scoped=OLD.operation IN ('npi.pilot.create','npi.pilot.result.record') "
    "OR OLD.subject_type IN ('pilot_run','pilot_observation'); END IF;\n"
    " IF TG_OP<>'DELETE' THEN scoped=scoped OR NEW.operation IN "
    "('npi.pilot.create','npi.pilot.result.record') OR NEW.subject_type IN "
    "('pilot_run','pilot_observation'); END IF;\n"
    " IF scoped AND TG_OP<>'INSERT' THEN\n"
    "  RAISE EXCEPTION 'Native Pilot receipt is immutable' USING ERRCODE='23514'; END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n"
    " RETURN NEW;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.protect_native_pilot_member() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE scoped boolean=false; old_scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'DELETE' THEN\n"
    "  SELECT EXISTS(SELECT 1 FROM public.action_receipts r WHERE r.tenant_id=NEW.tenant_id AND "
    "r.id=NEW.receipt_id\n"
    "   AND (r.operation IN ('npi.pilot.create','npi.pilot.result.record') OR r.subject_type IN "
    "('pilot_run','pilot_observation'))) INTO scoped;\n"
    " END IF;\n"
    " IF TG_OP<>'INSERT' THEN\n"
    "  SELECT EXISTS(SELECT 1 FROM public.action_receipts r WHERE r.tenant_id=OLD.tenant_id AND "
    "r.id=OLD.receipt_id\n"
    "   AND (r.operation IN ('npi.pilot.create','npi.pilot.result.record') OR r.subject_type IN "
    "('pilot_run','pilot_observation'))) INTO old_scoped;\n"
    " END IF;\n"
    " IF TG_OP<>'INSERT' AND (scoped OR old_scoped) THEN\n"
    "  IF TG_OP='UPDATE' AND TG_TABLE_NAME='outbox_events'\n"
    "   AND (to_jsonb(NEW)-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error'])\n"
    "    IS NOT DISTINCT FROM "
    "(to_jsonb(OLD)-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error']) THEN "
    "RETURN NEW; END IF;\n"
    "  RAISE EXCEPTION 'Native Pilot original audit event or request is immutable' USING "
    "ERRCODE='23514';\n"
    " END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n"
    " RETURN NEW;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.require_native_pilot_member() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "\n"
    "DECLARE r public.action_receipts;\n"
    "BEGIN\n"
    " IF TG_TABLE_NAME='action_receipts' THEN r=NEW;\n"
    " ELSE SELECT * INTO r FROM public.action_receipts WHERE tenant_id=NEW.tenant_id AND "
    "id=NEW.receipt_id; END IF;\n"
    " IF r.operation IN ('npi.pilot.create','npi.pilot.result.record') OR r.subject_type IN "
    "('pilot_run','pilot_observation') THEN\n"
    "  PERFORM public.assert_native_pilot_members(r.tenant_id,r.subject_id,r.subject_type::text);\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.require_native_pilot_root() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "BEGIN PERFORM public.assert_native_pilot_root(NEW.tenant_id,NEW.id); RETURN NULL; END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.require_native_pilot_observation() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "BEGIN PERFORM public.assert_native_pilot_observation(NEW.tenant_id,NEW.id); RETURN NULL; END;\n"
    "$native_pilot$",
    "CREATE FUNCTION public.reject_native_pilot_mutation() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_pilot$\n"
    "BEGIN RAISE EXCEPTION 'Native Pilot roots and observations are immutable' USING ERRCODE='23514'; "
    "END;\n"
    "$native_pilot$",
